A={(1,1),(1,2),(1,3),(1,4),(2,1),(3,1),(3,3),(3,4),(4,3)}
B={(1,1),(1,3),(2,1),(2,2),(3,3),(3,4),(4,2),(4,3)}
O={(2,3),(2,4),(3,2),(4,1),(4,4)}
transforms={}
for name,fn in [('id',lambda r,c:(r,c)),('flipH',lambda r,c:(r,5-c)),('flipV',lambda r,c:(5-r,c)),('rot90',lambda r,c:(c,5-r)),('rot180',lambda r,c:(5-r,5-c)),('rot270',lambda r,c:(5-c,r)),('transpose',lambda r,c:(c,r)),('anti',lambda r,c:(5-c,5-r))]:
 tb={fn(r,c) for r,c in B}; transforms[name]=tb
 print(name,'intersect',len(A&tb),A&tb,'xor',A^tb, 'match?', A&tb==O)
